package main

import "sort"

// MergeIntervals merges all overlapping intervals in the input slice and returns the merged result.
func MergeIntervals(in [][]int) [][]int {
	if len(in) == 0 {
		return nil
	}

	// Sort intervals by start time
	sort.Slice(in, func(i, j int) bool {
		return in[i][0] < in[j][0]
	})

	// Initialize the result with the first interval
	merged := make([][]int, 0, len(in))
	merged = append(merged, in[0])

	// Iterate through the remaining intervals and merge if overlapping
	for i := 1; i < len(in); i++ {
		last := merged[len(merged)-1]
		current := in[i]

		// If the current interval overlaps with the last merged interval, merge them
		if current[0] <= last[1] {
			// Update the end of the last merged interval if the current one extends further
			if current[1] > last[1] {
				last[1] = current[1]
			}
		} else {
			// No overlap, add the current interval as a new merged interval
			merged = append(merged, current)
		}
	}

	return merged
}
